import csv
import io
import json


def read_people(csv_text):
    reader = csv.DictReader(io.StringIO(csv_text))
    for column in ("name", "age", "city"):
        if column not in (reader.fieldnames or []):
            return [], [f"missing column: {column}"]
    people, errors = [], []
    for number, row in enumerate(reader, start=1):
        age = row["age"].strip()
        if not age.isdigit():
            errors.append(f"row {number}: bad age {age}")
            continue
        people.append({"name": row["name"], "age": int(age), "city": row["city"]})
    return people, errors


def to_json(people):
    return json.dumps(people, indent=2, sort_keys=True, ensure_ascii=False)


def write_csv(people):
    out = io.StringIO()
    writer = csv.DictWriter(out, fieldnames=["name", "age", "city"], lineterminator="\n")
    writer.writeheader()
    writer.writerows(people)
    return out.getvalue()

