import json as _json

DATA = 'city,name,age,notes\nLondon,Ada,36,x\n"New York, NY","Hopper, Grace",85,\nParis,Émile,abc,\nZürich,Linus,21,\n'

@test("reading")
def _():
    people, errors = read_people(DATA)
    check_eq(people, [{"name": "Ada", "age": 36, "city": "London"}, {"name": "Hopper, Grace", "age": 85, "city": "New York, NY"}, {"name": "Linus", "age": 21, "city": "Zürich"}])
    check_eq(errors, ["row 3: bad age abc"])

@test("missing columns")
def _():
    check_eq(read_people("name,city\nAda,London\n"), ([], ["missing column: age"]))
    check_eq(read_people(""), ([], ["missing column: name"]))

@test("json")
def _():
    text = to_json([{"name": "Linus", "age": 21, "city": "Zürich"}])
    check("Zürich" in text, "keep non-ASCII characters")
    check_eq(text, '[\n  {\n    "age": 21,\n    "city": "Zürich",\n    "name": "Linus"\n  }\n]')
    check_eq(_json.loads(text)[0]["age"], 21)

@test("writing CSV round trip")
def _():
    people, _ = read_people(DATA)
    text = write_csv(people)
    check(text.startswith("name,age,city\nAda,36,London\n"), "header and first row")
    check('"Hopper, Grace",85,"New York, NY"' in text, "fields with commas are quoted")
    check_eq(read_people(text)[0], people)

